function validate([logs]) {
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 1000) return 'logs needs 1 to 1000 entries.';
  for (const log of logs) {
    if (typeof log !== 'string' || log.length < 2 || log.length > 10) return 'Each entry has 2 to 10 characters.';
    if (log !== '../' && log !== './' && !/^[a-z0-9]+\/$/.test(log)) return 'Each entry is "../", "./" or a folder name made of lowercase letters and digits followed by "/".';
  }
  return null;
}

