function minOperations(logs) {
  const stack = [];
  for (const log of logs) {
    if (log === '../') {
      if (stack.length > 0) {
        stack.pop();
      }
    } else if (log !== './') {
      stack.push(log);
    }
  }
  return stack.length;
}

