function minOperations(logs) {
  let path = '';
  for (const log of logs) {
    const name = log.slice(0, -1);
    if (name === '..') path = path.slice(0, Math.max(0, path.lastIndexOf('/')));
    else if (name !== '.') path = path + '/' + name;
  }
  return path.split('/').length - 1;
}

