function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz0123456789';
  const name = (maxLen) => {
    const len = 1 + Math.floor(rand() * maxLen);
    let text = '';
    for (let i = 0; i < len; i++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 10);
  const down = 0.25 + rand() * 0.5;
  const stay = rand() * 0.25;
  const logs = [];
  for (let i = 0; i < n; i++) {
    const r = rand();
    if (r < down) logs.push((size === 'large' ? name(9) : ['a', 'b', 'd1', 'x9'][Math.floor(rand() * 4)]) + '/');
    else if (r < down + stay) logs.push('./');
    else logs.push('../');
  }
  return [logs];
}
